from save_review import save
save(1226,{2:'自动发射器是帝国载具使用的车载榴弹发射器。这种结构简单的六管武器安装在车体上，每轮齐射三枚榴弹，可装填破片、穿甲或致盲榴弹，用于近距离防御或施放烟幕。每具自动发射器携带六枚同类型榴弹。',6:'另一种半自主型号可安装在固定阵位、路障或载具上。每个预装弹筒装有三对破片榴弹或烟幕榴弹，既可由附近的操作人员遥控触发，也可设为在探测到移动或声音时自动启动。每次发射时，它会向正前方的45度扇形范围射出一对榴弹，以扰乱附近步兵的行动或使其失去方向感。'},{6:'semi-autonomous指半自主控制，并非半自动射击方式；本型号每次两枚，与前段型号每次三枚的区别照原文保留。'},[('Auto-launcher','自动发射器')])
save(1227,{2:'铁甲突击发射器安装在铁甲无畏机甲或百夫长装甲上，可发射进攻型和防御型榴弹。',4:'Ironclad Assault Launcher mounted on a Centurion 安装在百夫长装甲上的铁甲突击发射器'},terms=[('Ironclad Assault Launcher','铁甲突击发射器')])
save(1228,{2:'破片风暴榴弹发射器是原铸星际战士使用的一种榴弹发射器，装备于侵略者小队和救赎者无畏机甲，用来杀伤敌方人员。'},terms=[('Fragstorm Grenade Launcher','破片风暴榴弹发射器')])
save(1229,{2:'穿甲风暴榴弹发射器是反重力战车使用的一种自动榴弹发射器，能向敌军倾泻大量穿甲榴弹。'},terms=[('Krakstorm Grenade Launcher','穿甲风暴榴弹发射器')])
save(1230,{2:'射网枪，又称网枪，是一种用于限制中弹目标行动的武器。',7:'它会射出一种化学物质，膨胀后形成纤维丝束，将被覆盖的人缠住，使其无法行动。目标越是挣扎，纤维就收缩得越紧，最终会将被困者挤碎。有些网含有麻醉剂，能让猎物停止挣扎，因此更适合狩猎。这些网可以用专门的除网喷剂溶解。',9:'Genestealer Cultist with Webber 装备射网枪的基因窃取者教徒',11:'这类武器还有射网手枪和重型射网枪等衍生型号。',15:'剃刀射网枪——射出混有剃刀般锋利丝线的网；被困者试图挣脱时，这些丝线会将其撕裂。'},terms=[('Webber','射网枪'),('Web Pistol','射网手枪'),('Heavy Webber','重型射网枪'),('Razor Webber','剃刀射网枪')])
save(1231,{2:'阿斯塔特射网枪是星际战士用于捕获目标，或制服不肯配合却并无罪责的平民的射网枪。无论是逃跑的刺客，还是一小群市民，它都能迅速有效地使其失去行动能力。这种武器射出大量细丝，展开后形成一张黏性极强、几乎无法扯断的网。目标越挣扎，细丝就收得越紧，任何挣脱的尝试只会使其陷得更深。五小时后，网会自行分解并片片脱落。'},terms=[('Astartes Webber','阿斯塔特射网枪')])
save(1232,{2:'自动武器广泛用于整个帝国，其工作方式类似二十世纪的自动枪械。它们使用实弹，而不像激光武器那样采用便于反复充电的能源包，因此在持久战中更容易耗尽弹药。自动武器的优点在于技术门槛较低，即使科技落后的世界也能生产。',4:'由于自动武器在游戏规则中的表现与激光武器相同，除自动炮和战斗炮外，它们已从军队编成列表中移除。',6:'自动手枪和自动枪的威力与对应的激光手枪、激光枪相近，但自动炮与激光炮却有明显区别：它的单发威力不及激光炮，射速却更高。因此，在近期对帝国指挥官可选武器种类的精简中，自动炮仍得以保留。',10:'自动枪是一种基础武器，威力与激光枪相近，但正逐渐被后者取代。',13:'自动手枪是自动枪的小型版本，正逐渐被激光手枪取代。',16:'自动炮是射速快、射程远的重型自动武器，帝国军队至今仍在使用。',20:'宏炮是最重型的自动武器。它们威力巨大、重量惊人，射速相对较低，主要适合用于火力支援或防御。',23:'突击炮是一种六管火炮，通常安装在兰德掠袭者战车或星际战士的终结者装甲上。'},{4:'本段谈的是底稿所依据版本的游戏规则变化，不能据此理解为当前版本规则，或这些武器已在世界观中消失。',6:'“近期精简”仍承接前段的规则版本语境，不是指某位指挥官在设定中淘汰武器。'},[('Auto Weapon','自动武器'),('Autogun','自动枪'),('Autopistol','自动手枪'),('Autocannon','自动炮'),('Macro Cannon','宏炮'),('Assault Cannon','突击炮')])
